import { Router } from 'express';
import multer from 'multer';
import { requireExternalAuth, requireAccountType } from '../middleware/requireExternalAuth.js';
import { collaboration, circleMessages } from '../../customer/services/eventCircle.service.js';
import { listEventMedia, createEventMedia, moderateEventMedia, eventMemory } from '../../customer/services/eventMedia.service.js';
import { streamEventMedia } from '../../customer/routes/eventMedia.routes.js';
const router = Router();
const h = handler => (req, res, next) => Promise.resolve(handler(req, res)).catch(next);
const actor = req => ({ id: String(req.externalUser._id), vendorId: String(req.externalUser.vendorOrganization), type: 'VENDOR' });
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 20 * 1024 * 1024, files: 1 } });
router.use(requireExternalAuth, requireAccountType('VENDOR'));
router.get('/events/:id/circle', h(async (req, res) => res.json(await collaboration(actor(req), req.params.id))));
router.get('/events/:id/messages', h(async (req, res) => res.json(await circleMessages(actor(req), req.params.id, req.query))));
router.post('/events/:id/messages', h(async (req, res) => res.status(201).json(await circleMessages(actor(req), req.params.id, req.body, { post: true }))));
router.get('/events/:id/media', h(async (req, res) => res.json(await listEventMedia(actor(req), req.params.id, req.query))));
router.post('/events/:id/media', upload.single('file'), h(async (req, res) => res.status(201).json(await createEventMedia(actor(req), req.params.id, req.body, req.file))));
router.post('/events/:id/media/:assetId', h(async (req, res) => res.json(await moderateEventMedia(actor(req), req.params.id, req.params.assetId, req.body))));
router.get('/events/:id/memory', h(async (req, res) => res.json(await eventMemory(actor(req), req.params.id))));
router.get('/media/:assetId/file', h((req, res) => streamEventMedia(req, res, actor(req))));
export default router;
